import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import './App.css';
import Header from './components/Header';
import FightList from './pages/FightList';
import Player from './pages/Player';
import Library from './pages/Library';
import Annotate from './pages/Annotate';
import PipelineAccuracy from './pages/PipelineAccuracy';
import TrainingDataQA from './pages/TrainingDataQA';

export default function App() {
  return (
    <BrowserRouter>
      {/* Fixed background layer */}
      <div style={{ position: 'fixed', inset: 0, zIndex: 0, background: '#050709', overflow: 'hidden', pointerEvents: 'none' }}>
        {/* Ambient orbs */}
        <div style={{
          position: 'absolute', width: 700, height: 700, borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(0,180,255,0.13) 0%, transparent 68%)',
          top: -180, left: -150,
          animation: 'orb-drift-a 18s ease-in-out infinite',
        }} />
        <div style={{
          position: 'absolute', width: 600, height: 600, borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(124,58,237,0.11) 0%, transparent 68%)',
          bottom: -120, right: -100,
          animation: 'orb-drift-b 22s ease-in-out infinite',
        }} />
        <div style={{
          position: 'absolute', width: 400, height: 400, borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(255,100,50,0.08) 0%, transparent 68%)',
          top: '40%', right: '20%',
          animation: 'orb-drift-c 26s ease-in-out infinite',
        }} />

        {/* Film grain */}
        <div className="grain-overlay" />
      </div>

      {/* App shell */}
      <div style={{ position: 'relative', zIndex: 1, display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Header />
        <Routes>
          <Route path="/" element={<FightList />} />
          <Route path="/fights/:id" element={<Player />} />
          <Route path="/fights/:id/annotate" element={<Annotate />} />
          <Route path="/library" element={<Library />} />
          <Route path="/accuracy" element={<PipelineAccuracy />} />
          <Route path="/training-data" element={<TrainingDataQA />} />
          <Route path="/training-data/:action" element={<TrainingDataQA />} />
          <Route path="/training-data/:action/:eventId" element={<TrainingDataQA />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </BrowserRouter>
  );
}
export interface Fight {
  id: number;
  video_path: string;
  fps: number;
  width: number;
  height: number;
  created_at: string;
  state: string;
  labeled_at: string | null;
  purpose: string;
  reported_frames: number | null;
  decoded_frames: number | null;
  segmentation_needs_review: boolean;
  segmentation_review_reason: string | null;
  red_fighter_id: number | null;
  blue_fighter_id: number | null;
  red_fighter_name: string | null;
  blue_fighter_name: string | null;
}

/**
 * What the video is for. Set once at upload from the Upload dialog and never
 * written again — the AI pipeline does not touch it, so a `reference` fight
 * keeps its identity when it is re-run to produce predictions to score against.
 */
export type FightPurpose = 'training_data' | 'reference' | 'ai_labeled';

export const PURPOSE_LABELS: Record<FightPurpose, string> = {
  training_data: 'Training data',
  reference: 'Reference',
  ai_labeled: 'AI labeled',
};

/**
 * Deliberately avoids #ff4d4d/#3aa0ff (corner colours — a badge in either would
 * read as "red corner"), #ef4444 (error) and #f59e0b (the rounds-unverified
 * warning). Violet is new to the palette. Colour is a redundant channel here
 * anyway: every badge carries its text label.
 */
export const PURPOSE_COLORS: Record<FightPurpose, string> = {
  training_data: '#a3c900', // --green-500
  reference: '#a78bfa', // violet — no existing semantic
  ai_labeled: '#00daf3', // --cyan-400, the AI accent
};

export const PURPOSE_ICONS: Record<FightPurpose, string> = {
  training_data: 'model_training',
  reference: 'verified',
  ai_labeled: 'auto_awesome',
};

export const STATE_PROGRESS: Record<string, number> = {
  validating: 0,
  queued: 0,
  detecting: 10,
  tracking: 35,
  pose: 45,
  corners: 70,
  scoreboard: 78,
  segmenting: 85,
  analyzing: 92,
  completed: 100,
  labeling_in_progress: 96,
  labeling_complete: 100,
  failed: 0,
  invalid: 0,
};

export const STATE_LABELS: Record<string, string> = {
  validating: 'Validating video',
  queued: 'Queued',
  detecting: 'Detecting fighters',
  tracking: 'Tracking fighters',
  pose: 'Analyzing poses',
  corners: 'Identifying corners',
  scoreboard: 'Reading scoreboard',
  segmenting: 'Segmenting rounds',
  analyzing: 'Processing fight',
  completed: 'Completed',
  labeling_in_progress: 'Labeling in progress',
  labeling_complete: 'Labeling complete',
  failed: 'Failed',
  invalid: 'Invalid video',
};

/** States where the pipeline has stopped moving on its own — no more live SSE updates expected. */
export const TERMINAL_STATES = new Set([
  'completed',
  'failed',
  'invalid',
  'labeling_in_progress',
  'labeling_complete',
]);

/** Fight has real analysis data (events/frames/rounds) ready to review in the Player. */
export const isFightViewable = (state: string): boolean =>
  state === 'completed' || state === 'labeling_complete';

/** Fight has fighter_frames/rounds written and is waiting for the user to manually tag events. */
export const isLabelingReady = (state: string): boolean =>
  state === 'labeling_in_progress';

/** Source video failed full-decode validation and was never queued for processing. */
export const isInvalid = (state: string): boolean => state === 'invalid';

/**
 * Segmentation could not corroborate its own round list against the scoreboard,
 * so the rounds are a detection-only guess and should be confirmed by hand.
 * The pipeline sets this at segmentation time — see ai/video_processing/
 * fight_segmentation.py `_review_verdict`. Once labeling is complete, every
 * round has a hand-confirmed label-span (finish-labeling requires it), so the
 * guess has already been confirmed and the warning no longer applies.
 */
export const needsRoundReview = (fight: Fight): boolean =>
  fight.segmentation_needs_review === true && fight.state !== 'labeling_complete';
import type { Event, EventKind, EventSource } from '../types/Event';
import type { EvalRunResponse, EvalRunSummary, FixtureSummary } from '../types/EvalRun';
import type { Fight, FightPurpose } from '../types/Fight';
import type { Fighter } from '../types/Fighter';
import type { FighterFrame } from '../types/FighterFrame';
import type { Round } from '../types/Round';

export interface FetchEventsParams {
  source?: EventSource;
  kind?: EventKind;
  fighter_id?: number;
  action?: string;
  success?: boolean;
}

export interface CreateEventPayload {
  kind?: EventKind; // defaults to 'point' server-side
  frame: number;
  end_frame?: number | null;
  description?: string | null;
  corner?: number | null;
  action?: string | null;
  target?: string | null;
  success?: boolean | null;
  labeler?: string | null;
  value?: string | null;
}

export interface UpdateEventPayload {
  frame?: number;
  end_frame?: number;
  value?: string;
}

export const fetchEvents = async (fightId: number, params?: FetchEventsParams): Promise<Event[]> => {
  const query = new URLSearchParams();
  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined) query.append(key, String(value));
    });
  }
  const qs = query.toString();
  const response = await fetch(`/fights/${fightId}/events/${qs ? `?${qs}` : ''}`);
  if (!response.ok) throw new Error(`Failed to fetch events: ${response.statusText}`);
  return response.json();
};

export const createEvent = async (fightId: number, payload: CreateEventPayload): Promise<Event> => {
  const response = await fetch(`/fights/${fightId}/events/`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Failed to create event: ${response.statusText}`);
  }
  return response.json();
};

export const updateEvent = async (fightId: number, eventId: number, payload: UpdateEventPayload): Promise<Event> => {
  const response = await fetch(`/fights/${fightId}/events/${eventId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Failed to update event: ${response.statusText}`);
  }
  return response.json();
};

export const verifyEvent = async (fightId: number, eventId: number, isVerified: boolean | null): Promise<Event> => {
  const response = await fetch(`/fights/${fightId}/events/${eventId}/verify`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ is_verified: isVerified }),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Failed to verify event: ${response.statusText}`);
  }
  return response.json();
};

export const deleteEvent = async (fightId: number, eventId: number): Promise<void> => {
  const response = await fetch(`/fights/${fightId}/events/${eventId}`, { method: 'DELETE' });
  if (!response.ok) throw new Error(`Failed to delete event: ${response.statusText}`);
};

export const fetchFights = async (): Promise<Fight[]> => {
  const response = await fetch('/fights/');
  if (!response.ok) throw new Error(`Failed to fetch fights: ${response.statusText}`);
  return response.json();
};

export const fetchFighterFrames = async (fightId: number): Promise<FighterFrame[]> => {
  const response = await fetch(`/fights/${fightId}/frames/`);
  if (!response.ok) throw new Error(`Failed to fetch fighter frames: ${response.statusText}`);
  return response.json();
};

export const fetchRounds = async (fightId: number): Promise<Round[]> => {
  const response = await fetch(`/fights/${fightId}/rounds/`);
  if (!response.ok) throw new Error(`Failed to fetch rounds: ${response.statusText}`);
  return response.json();
};

export const fetchFighters = async (search?: string): Promise<Fighter[]> => {
  const params = search ? `?search=${encodeURIComponent(search)}` : '';
  const response = await fetch(`/fighters/${params}`);
  if (!response.ok) throw new Error(`Failed to fetch fighters: ${response.statusText}`);
  return response.json();
};

export const createFighter = async (data: {
  first_name: string;
  last_name: string;
  nickname?: string;
}): Promise<Fighter> => {
  const response = await fetch('/fighters/', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });
  if (!response.ok) throw new Error(`Failed to create fighter: ${response.statusText}`);
  return response.json();
};

export const uploadFight = async (
  file: File,
  redFighterId: number | undefined,
  blueFighterId: number | undefined,
  purpose: FightPurpose,
): Promise<Fight> => {
  const form = new FormData();
  form.append('file', file);
  if (redFighterId != null) form.append('red_fighter_id', String(redFighterId));
  if (blueFighterId != null) form.append('blue_fighter_id', String(blueFighterId));
  // `purpose` also picks the pipeline track server-side: only 'ai_labeled'
  // runs strike detection and the state machine.
  form.append('purpose', purpose);
  const response = await fetch('/fights/upload', { method: 'POST', body: form });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Upload failed: ${response.statusText}`);
  }
  return response.json();
};

export const finishLabeling = async (fightId: number): Promise<Fight> => {
  const response = await fetch(`/fights/${fightId}/finish-labeling`, { method: 'POST' });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Failed to finish labeling: ${response.statusText}`);
  }
  return response.json();
};

export const deleteFight = async (fightId: number): Promise<void> => {
  const response = await fetch(`/fights/${fightId}`, { method: 'DELETE' });
  if (!response.ok) throw new Error(`Failed to delete fight: ${response.statusText}`);
};

export const fetchFixtures = async (): Promise<FixtureSummary[]> => {
  const response = await fetch('/eval-runs/fixtures');
  if (!response.ok) throw new Error(`Failed to fetch fixtures: ${response.statusText}`);
  return response.json();
};

export const fetchEvalRuns = async (
  referenceFightId: number,
  scoredFightId?: number,
): Promise<EvalRunSummary[]> => {
  const query = new URLSearchParams({ reference_fight_id: String(referenceFightId) });
  if (scoredFightId != null) query.append('scored_fight_id', String(scoredFightId));
  const response = await fetch(`/eval-runs/?${query.toString()}`);
  if (!response.ok) throw new Error(`Failed to fetch eval runs: ${response.statusText}`);
  return response.json();
};

export const fetchEvalRun = async (runId: number): Promise<EvalRunResponse> => {
  const response = await fetch(`/eval-runs/${runId}`);
  if (!response.ok) throw new Error(`Failed to fetch eval run: ${response.statusText}`);
  return response.json();
};

export const createEvalRun = async (
  referenceFightId: number,
  scoredFightId: number,
  toleranceSecs?: number,
): Promise<EvalRunResponse> => {
  const response = await fetch('/eval-runs/', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      reference_fight_id: referenceFightId,
      scored_fight_id: scoredFightId,
      tolerance_secs: toleranceSecs ?? null,
    }),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.detail ?? `Failed to run scoring: ${response.statusText}`);
  }
  return response.json();
};

