346	        {narrow ? (
347	          <div style={{ height: 420 }}>
348	            <LiveFeed
349	              events={events}
350	              currentFrame={currentFrame}
351	              fps={fps}
352	              onSeek={handleSeek}
353	              redName={displayFighters.red.name}
354	              blueName={displayFighters.blue.name}
355	              redFighterId={selectedFight?.red_fighter_id}
356	              rounds={rounds}
357	              cornerSwapSpans={cornerSwapSpans}
