361	          <div style={{ position: 'relative' }}>
362	            <div style={{ position: 'absolute', inset: 0 }}>
363	              <LiveFeed
364	                events={events}
365	                currentFrame={currentFrame}
366	                fps={fps}
367	                onSeek={handleSeek}
368	                redName={displayFighters.red.name}
369	                blueName={displayFighters.blue.name}
370	                redFighterId={selectedFight?.red_fighter_id}
371	                rounds={rounds}
372	                cornerSwapSpans={cornerSwapSpans}
373	              />
374	            </div>
375	          </div>
376	        )}
377	      </div>
378	
379	      {/* FIGHT STATISTICS */}
380	      {!eventsLoading && (
381	        <FightStatistics
382	          currentFrame={currentFrame}
383	          events={events}
384	          fps={fps}
385	          rounds={rounds}
386	          fighters={displayFighters}
387	          redFighterId={selectedFight?.red_fighter_id}
