390	
391	      {/* MOMENTUM */}
392	      <Momentum
393	        time={currentTime}
394	        duration={duration}
395	        r1EndSeconds={r1EndSeconds}
396	        events={events}
397	        fps={fps}
398	        fighters={displayFighters}
399	        redFighterId={selectedFight?.red_fighter_id}
400	      />
401	
402	      {/* MATCHUP */}
403	      <MatchupCard fighters={displayFighters} />
404	    </div>
405	  );
406	}
