595	            overlayRef={overlayRef}
596	            src={videoSrc}
597	            isPlaying={isPlaying}
598	            onTimeUpdate={() => { const v = videoRef.current; if (v) setCurrentTime(v.currentTime); }}
599	            onLoadedMetadata={() => { const v = videoRef.current; if (v) setDuration(v.duration); }}
600	            onPlay={() => setIsPlaying(true)}
601	            onPause={() => setIsPlaying(false)}
602	            onTogglePlay={togglePlay}
603	            onStepForward={() => stepFrame(1)}
604	            onStepBackward={() => stepFrame(-1)}
605	            frameMap={frameMap}
606	            fightWidth={selectedFight.width}
607	            fightHeight={selectedFight.height}
608	            currentRound={currentRound}
609	            selectedCorner={selected}
610	            redName={redName}
611	            blueName={blueName}
612	            toast={toast}
613	          />
614	
615	          <VideoControls
616	            isPlaying={isPlaying}
617	            currentTime={currentTime}
618	            duration={duration}
619	            onTogglePlay={togglePlay}
620	            onSeek={handleSeek}
621	            onStepBackward={() => stepFrame(-1)}
622	            onStepForward={() => stepFrame(1)}
623	          />
624	
625	          <FrameInfo currentFrame={currentFrame} currentMs={currentMs} fps={fps} />
626	
627	          <KeyboardLegend />
628	        </div>
629	
630	        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
631	          <div className="glass" style={{ padding: '18px 18px 20px', borderRadius: 14 }}>
632	            <div className="label" style={{ fontSize: 9.5, marginBottom: 11 }}>Active fighter</div>
633	            <FighterSelectCard
634	              selected={selected}
635	              onSelect={c => setSelected(s => (s === c ? null : c))}
636	              redName={redName}
637	              blueName={blueName}
638	              hint={hint}
639	            />
640	            <hr className="divider" style={{ margin: '18px 0 16px' }} />
641	            <EventPalette selected={selected !== null} onLog={logTool} onFightEnd={() => setEndOpen(true)} />
642	          </div>
643	        </div>
644	      </div>
645	
646	      <AnnotationPanel
647	        events={events}
648	        spans={spans}
649	        rounds={rounds}
650	        duration={duration}
651	        fps={fps}
652	        currentFrame={currentFrame}
653	        onSeek={seekToFrame}
654	        onSetPlaying={setIsPlaying}
655	        onDelete={removeEvent}
656	        onUpdateSpan={updateSpan}
657	        onDeleteSpan={removeSpan}
658	        flashId={flashId}
659	        selectedEventId={selectedEventId}
660	        onSelectEvent={setSelectedEventId}
661	        redName={redName}
662	        blueName={blueName}
663	        describe={describe}
664	      />
665	
666	      {endOpen && (
667	        <FightEndModal
668	          currentRound={currentRound}
669	          timeLabel={`${Math.floor(currentTime / 60)}:${String(Math.floor(currentTime % 60)).padStart(2, '0')}`}
670	          redName={redName}
671	          blueName={blueName}
672	          onClose={() => setEndOpen(false)}
673	          onConfirm={confirmFightEnd}
674	        />
675	      )}
676	    </div>
677	  );
678	}
