1	import { useEffect, useCallback } from 'react';
2	import type { QAEvent } from '../../hooks/useTrainingDataEvents';
3	import type { TrainingClass } from '../../utils/trainingDataTaxonomy';
4	import type { ClassStats } from '../../utils/trainingDataStats';
5	import { formatFrameClock } from '../annotate/taxonomy';
6	import { fightLabel } from '../../utils/fightLabel';
7	import ClipPlayer from './ClipPlayer';
8	import VerdictBadge from './VerdictBadge';
9	
10	const CORNER_C: Record<number, string> = { 0: 'var(--f-red)', 1: 'var(--f-blue)' };
11	
12	function Meta({ k, v, mono, tone }: { k: string; v: React.ReactNode; mono?: boolean; tone?: string }) {
13	  return (
14	    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 14, padding: '7px 0', borderBottom: '1px solid rgba(255,255,255,0.045)' }}>
15	      <span style={{ fontSize: 10.5, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'rgba(255,255,255,0.28)' }}>{k}</span>
16	      <span style={{ fontSize: 11.5, fontWeight: 700, color: tone ?? 'var(--text-secondary)', textAlign: 'right', fontFamily: mono ? 'ui-monospace,Menlo,monospace' : 'inherit', fontVariantNumeric: 'tabular-nums' }}>{v}</span>
17	    </div>
18	  );
19	}
20	
21	interface EventReviewProps {
22	  event: QAEvent;
23	  cls: TrainingClass;
24	  onVerdict: (isVerified: boolean | null) => void;
25	  onBack: () => void;
26	  onJumpRelative: (delta: 1 | -1) => void;
27	  onJumpTo: (id: number) => void;
28	  queue: QAEvent[];
29	  pos: ClassStats;
30	  narrow?: boolean;
31	}
32	
33	export default function EventReview({ event, cls, onVerdict, onBack, onJumpRelative, onJumpTo, queue, pos, narrow }: EventReviewProps) {
34	  const v = event.is_verified;
35	
36	  const act = useCallback((target: boolean) => {
37	    onVerdict(v === target ? null : target);
38	  }, [v, onVerdict]);
39	
40	  useEffect(() => {
41	    const onKey = (e: KeyboardEvent) => {
42	      const tag = (e.target as HTMLElement)?.tagName;
43	      if (tag === 'INPUT') return;
44	      if (e.key === 'c' || e.key === 'C') act(true);
45	      else if (e.key === 'x' || e.key === 'X') act(false);
46	      else if (e.key === 'ArrowRight') onJumpRelative(1);
47	      else if (e.key === 'ArrowLeft') onJumpRelative(-1);
48	      else if (e.key === 'Escape') onBack();
49	    };
50	    window.addEventListener('keydown', onKey);
51	    return () => window.removeEventListener('keydown', onKey);
52	  }, [act, onJumpRelative, onBack]);
53	
54	  return (
55	    <div style={{ display: 'grid', gridTemplateColumns: narrow ? 'minmax(0,1fr)' : 'minmax(0,1fr) 330px', gap: 16, alignItems: 'start' }}>
56	      <div style={{ display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 }}>
57	        <div className="glass" style={{ padding: '14px 14px 12px' }}>
58	          <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 11 }}>
59	            <span style={{ width: 10, height: 10, borderRadius: 3, flexShrink: 0, background: event.corner != null ? CORNER_C[event.corner] : 'var(--text-disabled)' }} />
60	            <div style={{ minWidth: 0 }}>
61	              <div className="font-display" style={{ fontSize: 22, lineHeight: 1, color: 'var(--text-primary)' }}>
62	                {cls.name}{event.target && <span> · {event.target}</span>}
63	              </div>
64	              <div style={{ marginTop: 3, fontSize: 11, fontWeight: 600, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>
65	                {fightLabel(event.fight)} · {formatFrameClock(event.frame, event.fight.fps)} · f{event.frame}
66	              </div>
67	            </div>
68	          </div>
69	          <ClipPlayer fight={event.fight} frame={event.frame} corner={event.corner} />
70	        </div>
71	
72	        <div className="glass" style={{ display: 'flex', alignItems: 'center', gap: 20, flexWrap: 'wrap', padding: '14px 16px' }}>
73	          <div style={{ minWidth: 0 }}>
74	            <div className="label" style={{ marginBottom: 5 }}>Is this training-worthy?</div>
75	            <div style={{ fontSize: 11.5, fontWeight: 500, lineHeight: 1.5, color: 'var(--text-muted)', maxWidth: '44ch' }}>
76	              Confirm keeps the event in the training export. Decline drops it.
77	            </div>
78	          </div>
79	          <div style={{ display: 'flex', gap: 10, marginLeft: 'auto', flexWrap: 'wrap' }}>
80	            <button
81	              type="button"
82	              onClick={() => act(false)}
83	              style={{
84	                display: 'inline-flex', alignItems: 'center', gap: 8, padding: '11px 20px', borderRadius: 11,
85	                fontFamily: 'inherit', fontSize: 13.5, fontWeight: 800, cursor: 'pointer', border: '1px solid',
86	                background: v === false ? '#ef4444' : 'rgba(239,68,68,0.12)',
87	                borderColor: v === false ? '#ef4444' : 'rgba(239,68,68,0.34)',
88	                color: v === false ? '#2a0606' : '#f87171',
89	              }}
