  /**
   * `corner`, flipped for display if this event's frame falls inside one of
   * its fight's confirmed `corner_swap` spans — same display-only correction
   * FighterOverlay/describeEvent apply elsewhere. `corner` itself stays the
   * raw label track-slot (see label-events-corner-is-box-not-person) and is
   * what still gets passed to ClipPlayer/FighterOverlay's `highlightCorner`,
   * since that matches against `fighter_frames.corner`, which lives in the
   * same unswapped slot space. `displayCorner` is for showing the reviewer
   * which corner actually threw the strike — text/colour only.
   */
  displayCorner: 0 | 1 | null;
}

/**
 * Every reviewable hand-labelled point event across every labelled fight —
 * Training Data QA is cross-fight, unlike Player/Annotate which scope to one
 * `fightId`. Only `training_data`/`reference` fights that have actually
 * reached Annotate carry `source='label'` rows; an `ai_labeled` fight's
 * pipeline run never writes one.
 */
export const useTrainingDataEvents = () => {
  const [events, setEvents] = useState<QAEvent[]>([]);
  const [fights, setFights] = useState<Fight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(() => {
    setLoading(true);
    setError(null);
    fetchFights()
      .then(async (allFights) => {
        const labelled = allFights.filter(
          (f) => f.purpose !== 'ai_labeled'
            && (f.state === 'labeling_in_progress' || f.state === 'labeling_complete'),
        );
        setFights(labelled);
        const perFight = await Promise.all(
          labelled.map((f) =>
            fetchEvents(f.id, { source: 'label', kind: 'point' }).then((evs) =>
              evs
                .filter((e) => TRAINING_ACTIONS.has(e.action ?? ''))
                .map((e) => ({ ...e, fight: f })),
            ),
          ),
        );
        setEvents(perFight.flat());
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  const setVerdict = useCallback((eventId: number, fightId: number, isVerified: boolean | null) => {
    setEvents((prev) => prev.map((e) => (e.id === eventId ? { ...e, is_verified: isVerified } : e)));
    verifyEvent(fightId, eventId, isVerified).catch(() => {
      // Roll back to the server's actual state on failure.
      load();
    });
  }, [load]);

  return { events, fights, loading, error, setVerdict, refetch: load };
};

import { useEffect, useCallback } from 'react';
import type { QAEvent } from '../../hooks/useTrainingDataEvents';
import type { TrainingClass } from '../../utils/trainingDataTaxonomy';
import type { ClassStats } from '../../utils/trainingDataStats';
import { formatFrameClock } from '../annotate/taxonomy';
import { fightLabel } from '../../utils/fightLabel';
import ClipPlayer from './ClipPlayer';
import VerdictBadge from './VerdictBadge';

const CORNER_C: Record<number, string> = { 0: 'var(--f-red)', 1: 'var(--f-blue)' };

function Meta({ k, v, mono, tone }: { k: string; v: React.ReactNode; mono?: boolean; tone?: string }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 14, padding: '7px 0', borderBottom: '1px solid rgba(255,255,255,0.045)' }}>
      <span style={{ fontSize: 10.5, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'rgba(255,255,255,0.28)' }}>{k}</span>
      <span style={{ fontSize: 11.5, fontWeight: 700, color: tone ?? 'var(--text-secondary)', textAlign: 'right', fontFamily: mono ? 'ui-monospace,Menlo,monospace' : 'inherit', fontVariantNumeric: 'tabular-nums' }}>{v}</span>
    </div>
  );
}

interface EventReviewProps {
  event: QAEvent;
  cls: TrainingClass;
  onVerdict: (isVerified: boolean | null) => void;
  onBack: () => void;
  onJumpRelative: (delta: 1 | -1) => void;
  onJumpTo: (id: number) => void;
  queue: QAEvent[];
  pos: ClassStats;
  narrow?: boolean;
}

export default function EventReview({ event, cls, onVerdict, onBack, onJumpRelative, onJumpTo, queue, pos, narrow }: EventReviewProps) {
  const v = event.is_verified;

  const act = useCallback((target: boolean) => {
    onVerdict(v === target ? null : target);
  }, [v, onVerdict]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT') return;
      if (e.key === 'c' || e.key === 'C') act(true);
      else if (e.key === 'x' || e.key === 'X') act(false);
      else if (e.key === 'ArrowRight') onJumpRelative(1);
      else if (e.key === 'ArrowLeft') onJumpRelative(-1);
      else if (e.key === 'Escape') onBack();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [act, onJumpRelative, onBack]);

  return (
    <div style={{ display: 'grid', gridTemplateColumns: narrow ? 'minmax(0,1fr)' : 'minmax(0,1fr) 330px', gap: 16, alignItems: 'start' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 }}>
        <div className="glass" style={{ padding: '14px 14px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 11 }}>
            <span style={{ width: 10, height: 10, borderRadius: 3, flexShrink: 0, background: event.corner != null ? CORNER_C[event.corner] : 'var(--text-disabled)' }} />
            <div style={{ minWidth: 0 }}>
              <div className="font-display" style={{ fontSize: 22, lineHeight: 1, color: 'var(--text-primary)' }}>
                {cls.name}{event.target && <span> · {event.target}</span>}
              </div>
              <div style={{ marginTop: 3, fontSize: 11, fontWeight: 600, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>
                {fightLabel(event.fight)} · {formatFrameClock(event.frame, event.fight.fps)} · f{event.frame}
              </div>
            </div>
          </div>
          <ClipPlayer fight={event.fight} frame={event.frame} corner={event.corner} />
        </div>

        <div className="glass" style={{ display: 'flex', alignItems: 'center', gap: 20, flexWrap: 'wrap', padding: '14px 16px' }}>
          <div style={{ minWidth: 0 }}>
            <div className="label" style={{ marginBottom: 5 }}>Is this training-worthy?</div>
            <div style={{ fontSize: 11.5, fontWeight: 500, lineHeight: 1.5, color: 'var(--text-muted)', maxWidth: '44ch' }}>
              Confirm keeps the event in the training export. Decline drops it.
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10, marginLeft: 'auto', flexWrap: 'wrap' }}>
            <button
              type="button"
              onClick={() => act(false)}
              style={{
                display: 'inline-flex', alignItems: 'center', gap: 8, padding: '11px 20px', borderRadius: 11,
                fontFamily: 'inherit', fontSize: 13.5, fontWeight: 800, cursor: 'pointer', border: '1px solid',
                background: v === false ? '#ef4444' : 'rgba(239,68,68,0.12)',
                borderColor: v === false ? '#ef4444' : 'rgba(239,68,68,0.34)',
                color: v === false ? '#2a0606' : '#f87171',
              }}
            >
              <span className="material-symbols-outlined" style={{ fontSize: 18 }}>close</span>Decline
              <kbd style={{ display: 'inline-grid', placeItems: 'center', minWidth: 17, height: 17, borderRadius: 4, background: 'rgba(0,0,0,0.28)', fontSize: 9.5, fontWeight: 800, fontFamily: 'ui-monospace,Menlo,monospace', opacity: 0.75 }}>X</kbd>
            </button>
            <button
              type="button"
              onClick={() => act(true)}
              style={{
                display: 'inline-flex', alignItems: 'center', gap: 8, padding: '11px 20px', borderRadius: 11,
                fontFamily: 'inherit', fontSize: 13.5, fontWeight: 800, cursor: 'pointer', border: '1px solid',
                background: v === true ? '#0ca30c' : 'rgba(12,163,12,0.14)',
                borderColor: v === true ? '#0ca30c' : 'rgba(12,163,12,0.38)',
                color: v === true ? '#04180a' : '#4ade5e',
              }}
            >
              <span className="material-symbols-outlined" style={{ fontSize: 18 }}>check</span>Confirm
              <kbd style={{ display: 'inline-grid', placeItems: 'center', minWidth: 17, height: 17, borderRadius: 4, background: 'rgba(0,0,0,0.28)', fontSize: 9.5, fontWeight: 800, fontFamily: 'ui-monospace,Menlo,monospace', opacity: 0.75 }}>C</kbd>
            </button>
          </div>
        </div>
      </div>

      <aside style={{ display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 }}>
        <div className="glass" style={{ padding: '16px 18px 18px' }}>
          <div className="label" style={{ marginBottom: 8 }}>Event</div>
          <Meta k="Verdict" v={<VerdictBadge isVerified={v} sm />} />
          <Meta k="Exports as" v={cls.action} mono />
          <Meta k="Corner" v={event.corner === 0 ? 'Red slot' : event.corner === 1 ? 'Blue slot' : 'None'} tone={event.corner != null ? CORNER_C[event.corner] : undefined} />
          <Meta k="Target" v={event.target ?? 'Non-specific'} />
          <Meta k="Frame" v={`f${event.frame}`} mono />
          <Meta k="Timecode" v={formatFrameClock(event.frame, event.fight.fps)} mono />
          <Meta k="Labeller" v={event.labeler ?? 'Not recorded'} />
          <Meta k="Fight" v={fightLabel(event.fight)} />
        </div>

        <div className="glass" style={{ padding: '16px 18px 18px' }}>
          <div className="label" style={{ marginBottom: 9 }}>Queue · {cls.name}</div>
          <div style={{ display: 'flex', height: 5, borderRadius: 3, background: 'rgba(255,255,255,0.05)', overflow: 'hidden' }}>
            <div style={{ width: `${(pos.reviewed / pos.total) * 100}%`, background: 'var(--cyan-400)' }} />
          </div>
          <div style={{ marginTop: 6, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>{pos.reviewed} of {pos.total} reviewed · {pos.pending} pending</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginTop: 11, flexWrap: 'wrap' }}>
            <button type="button" className="btn-glass" onClick={() => onJumpRelative(-1)} style={{ padding: '6px 11px', fontSize: 11.5, borderRadius: 8, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
              <span className="material-symbols-outlined" style={{ fontSize: 14 }}>chevron_left</span>Prev
            </button>
            <button type="button" className="btn-glass" onClick={() => onJumpRelative(1)} style={{ padding: '6px 11px', fontSize: 11.5, borderRadius: 8, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
              Next<span className="material-symbols-outlined" style={{ fontSize: 14 }}>chevron_right</span>
            </button>
            <span style={{ flex: 1 }} />
            <button type="button" className="btn-glass" onClick={onBack} style={{ padding: '6px 11px', fontSize: 11.5, borderRadius: 8 }}>All events</button>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 11, paddingTop: 10, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
            {queue.slice(0, 4).map((q) => (
              <button
                key={q.id}
                type="button"
                onClick={() => onJumpTo(q.id)}
                style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 9px', borderRadius: 8, background: 'rgba(0,0,0,0.22)', border: '1px solid var(--border-subtle)', cursor: 'pointer', fontFamily: 'inherit' }}
              >
                <span style={{ width: 7, height: 7, borderRadius: 2, background: q.corner != null ? CORNER_C[q.corner] : 'var(--text-disabled)', flexShrink: 0 }} />
                <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11, fontWeight: 700, color: 'var(--text-secondary)' }}>{formatFrameClock(q.frame, q.fight.fps)}</span>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{fightLabel(q.fight).split(' vs ')[0]}</span>
              </button>
            ))}
            {queue.length === 0 && <div style={{ marginTop: 4, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>Nothing left pending in this class.</div>}
          </div>
        </div>
      </aside>
    </div>
  );
}

import { useState } from 'react';
import type { QAEvent } from '../../hooks/useTrainingDataEvents';
import type { TrainingClass } from '../../utils/trainingDataTaxonomy';
import { formatFrameClock } from '../annotate/taxonomy';
import { fightLabel } from '../../utils/fightLabel';
import VerdictBadge from './VerdictBadge';
import { classStats, verdictKey } from '../../utils/trainingDataStats';

const CORNER_C: Record<number, string> = { 0: 'var(--f-red)', 1: 'var(--f-blue)' };
const FILTERS = ['All', 'Pending', 'Confirmed', 'Declined'] as const;

interface EventTableProps {
  cls: TrainingClass;
  events: QAEvent[];
  onBack: () => void;
  onOpen: (id: number) => void;
}

export default function EventTable({ cls, events, onBack, onOpen }: EventTableProps) {
  const [filter, setFilter] = useState<(typeof FILTERS)[number]>('All');

  const s = classStats(events);

  const rows = events
    .filter((e) => {
      const v = verdictKey(e.is_verified);
      if (filter === 'Pending' && v !== 'pending') return false;
      if (filter === 'Confirmed' && v !== 'confirmed') return false;
      if (filter === 'Declined' && v !== 'declined') return false;
      return true;
    })
    .sort((a, b) => (a.fight.id === b.fight.id ? a.frame - b.frame : a.fight.id - b.fight.id));

  const firstPending = events.find((e) => e.is_verified == null);

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 14, flexWrap: 'wrap' }}>
        <button type="button" className="btn-glass" onClick={onBack} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 10px', fontSize: 11.5, fontWeight: 700, borderRadius: 8 }}>
          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>arrow_back</span>All classes
        </button>
        <span style={{ color: 'var(--text-disabled)', fontSize: 12 }}>/</span>
        <span style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-secondary)' }}>{cls.name}</span>
      </div>

      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 18, flexWrap: 'wrap', marginBottom: 16 }}>
        <div style={{ minWidth: 0 }}>
          <h1 className="font-display" style={{ fontSize: 32, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>{cls.name}</h1>
          <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
            {s.total} labelled events · exports as <code style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11.5, color: '#9fe8f4' }}>{cls.action}</code>
          </p>
        </div>
        <button
          type="button"
          className="btn-primary"
          disabled={!firstPending}
          onClick={() => firstPending && onOpen(firstPending.id)}
          style={{
            marginLeft: 'auto', background: 'linear-gradient(135deg, #00daf3 0%, #0099b0 100%)', color: '#001f24',
            fontWeight: 700, fontSize: 13, border: 'none', borderRadius: 10, padding: '9px 16px',
            display: 'inline-flex', alignItems: 'center', gap: 6,
            boxShadow: firstPending ? '0 0 16px rgba(0,218,243,0.2)' : 'none', opacity: firstPending ? 1 : 0.45,
            cursor: firstPending ? 'pointer' : 'default',
          }}
        >
          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>play_arrow</span>
          {s.pending ? `Review ${s.pending} pending` : 'All reviewed'}
        </button>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 11, flexWrap: 'wrap', padding: '9px 12px', marginBottom: 14, borderRadius: 12, background: 'rgba(255,255,255,0.028)', border: '1px solid var(--border-subtle)' }}>
        <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)' }}>
          {FILTERS.map((f) => (
            <button key={f} type="button" className={'pill' + (filter === f ? ' active' : '')} onClick={() => setFilter(f)} style={{ padding: '4px 9px', fontSize: 11 }}>{f}</button>
          ))}
        </div>
        <span style={{ flex: 1 }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-muted)' }}>{rows.length} shown</span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {rows.map((e) => (
          <button
            key={e.id}
            type="button"
            onClick={() => onOpen(e.id)}
            style={{
              display: 'grid', gridTemplateColumns: '74px minmax(0,1fr) auto 18px', gap: 13, alignItems: 'center',
              padding: '10px 12px', borderRadius: 11, background: 'rgba(255,255,255,0.022)', border: '1px solid var(--border-subtle)',
              cursor: 'pointer', fontFamily: 'inherit', textAlign: 'left',
            }}
          >
            <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 12, fontWeight: 700, color: 'var(--text-primary)' }}>
              {formatFrameClock(e.frame, e.fight.fps)}
            </span>
            <span style={{ display: 'flex', flexDirection: 'column', gap: 3, minWidth: 0 }}>
              <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {fightLabel(e.fight)}
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
                <span style={{ width: 7, height: 7, borderRadius: 2, background: e.corner != null ? CORNER_C[e.corner] : 'var(--text-disabled)', flexShrink: 0 }} />
                {e.corner === 0 ? 'Red slot' : e.corner === 1 ? 'Blue slot' : 'No corner'} · {e.target ?? 'non-specific'}
              </span>
            </span>
            <VerdictBadge isVerified={e.is_verified} sm />
            <span className="material-symbols-outlined" style={{ fontSize: 16, color: 'var(--text-disabled)' }}>chevron_right</span>
          </button>
        ))}
        {rows.length === 0 && (
          <div style={{ padding: 26, textAlign: 'center', fontSize: 12, fontWeight: 600, color: 'var(--text-muted)' }}>
            No events match this filter.
          </div>
        )}
      </div>
    </div>
  );
}

