const v = document.querySelector('video');
window.__log = [];
const origRVFC = HTMLVideoElement.prototype.requestVideoFrameCallback;
v.requestVideoFrameCallback = function(cb) {
  return origRVFC.call(this, (now, meta) => {
    window.__log.push({ t: performance.now(), mediaTime: +meta.mediaTime.toFixed(4) });
    cb(now, meta);
  });
};
// also track currentTime writes
let _ct = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, 'currentTime');
Object.defineProperty(v, 'currentTime', {
  get() { return _ct.get.call(this); },
  set(val) { window.__log.push({ t: performance.now(), seekTo: +val.toFixed(4) }); _ct.set.call(this, val); },
